import {useMemo,useState} from 'react'
import {AlertCircle,Camera,ChevronRight,Plus,Search} from 'lucide-react'
import {integer,money,vehicleName} from '../lib/format'
import {vehicleAgeDays} from '../domain/priorities'
import {vehicleCompleteness} from '../domain/garage'
import {PrivateImage} from '../components/PrivateImage'
import type {TenantData} from '../types'
import '../garage.css'

export function GaragePage({data,onVehicle,onCreate,writable}:{data:TenantData;onVehicle:(id:string)=>void;onCreate:()=>void;writable:boolean}){
  const [query,setQuery]=useState('');const [status,setStatus]=useState('ALL')
  const mediaByVehicle=useMemo(()=>{const m=new Map<string,TenantData['media']>();for(const x of data.media){const arr=m.get(x.vehicle_id)||[];arr.push(x);m.set(x.vehicle_id,arr)}return m},[data.media])
  const statuses=[...new Set(data.vehicles.map(v=>v.status).filter(Boolean))] as string[]
  const rows=data.vehicles.filter(v=>!v.deleted_at).filter(v=>status==='ALL'||v.status===status).filter(v=>`${vehicleName(v)} ${v.plate||''} ${v.vin||''}`.toLowerCase().includes(query.toLowerCase()))
  return <><div className="page-heading garage-heading"><div><p className="eyebrow">INVENTARIO OPERATIVO</p><h1>Garage</h1><p>Foto, completezza e problemi prima dei dettagli.</p></div><div className="garage-heading-actions"><div className="mini-stat"><span>AUTO</span><b>{data.vehicles.length}</b></div>{writable&&<button data-testid="new-vehicle" className="primary garage-new" onClick={onCreate}><Plus/>Nuova auto</button>}</div></div><div className="toolbar"><label className="search-input"><Search/><input id="global-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Targa, modello o telaio…"/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">Tutti gli stati</option>{statuses.map(s=><option key={s}>{s.replaceAll('_',' ')}</option>)}</select></div><div className="vehicle-grid garage-photo-grid">{rows.map(v=>{const media=(mediaByVehicle.get(v.id)||[]).filter(x=>(x.kind||'PHOTO')==='PHOTO');const cover=media.find(x=>x.is_cover)||media[0];const age=vehicleAgeDays(v);const completeness=vehicleCompleteness(v,media.length);const issues=[...completeness.missing.slice(0,2),age>=60&&v.status==='IN_VENDITA'?`${age} gg in stock`:null].filter(Boolean);return <button data-testid={`vehicle-card-${v.id}`} key={v.id} className="vehicle-card-v2 garage-photo-card" onClick={()=>onVehicle(v.id)}><div className="garage-card-media"><PrivateImage objectKey={cover?.object_key||v.cover_object_key} alt={vehicleName(v)} className="garage-card-photo"/><span className="status-pill media-status">{(v.status||'—').replaceAll('_',' ')}</span><span className={`completeness-badge ${completeness.percent===100?'complete':''}`}>{completeness.percent}%</span></div><div className="garage-card-copy"><div><h3>{vehicleName(v)}</h3><p>{v.plate||'Targa —'} · {v.year||'—'} · {integer(v.mileage)} km</p></div>{issues.length>0&&<span className="issue-pill"><AlertCircle/> {issues.join(' · ')}</span>}</div><div className="vehicle-card-bottom"><div><span>PREZZO</span><b>{v.asking_price?money(v.asking_price):'Da impostare'}</b></div><div><span><Camera size={14}/> FOTO</span><b>{media.length}</b></div><ChevronRight/></div></button>})}</div>{!rows.length&&<div className="empty-state">Nessuna auto corrisponde ai filtri.</div>}</>}
