import {CalendarDays,CheckCircle2,Clock,Plus,Save,X} from 'lucide-react'
import {useEffect,useMemo,useState} from 'react'
import {completeCalendarEvent,saveCalendarEvent} from '../lib/api'
import {fullDate} from '../lib/format'
import type {CalendarEvent,TenantData} from '../types'
const active=(e:CalendarEvent)=>!['DONE','CANCELLED','CHIUSO'].includes(e.status||'')
const customerName=(data:TenantData,id?:string|null)=>{const c=id?data.customers.find(x=>x.id===id):undefined;return c?[c.first_name,c.last_name].filter(Boolean).join(' '):''}
const vehicleName=(data:TenantData,id?:string|null)=>{const v=id?data.vehicles.find(x=>x.id===id):undefined;return v?[v.brand,v.model,v.plate].filter(Boolean).join(' '):''}
export function CalendarPage({data,writable,onRefresh,focusVehicleId,focusCustomerId,focusKey=0,onFocusConsumed}:{data:TenantData;writable:boolean;onRefresh:()=>Promise<void>;focusVehicleId?:string|null;focusCustomerId?:string|null;focusKey?:number;onFocusConsumed?:()=>void}){const [creating,setCreating]=useState(false);const [title,setTitle]=useState('');const [startsAt,setStartsAt]=useState('');const [priority,setPriority]=useState('NORMAL');const [customerId,setCustomerId]=useState('');const [vehicleId,setVehicleId]=useState('');const [note,setNote]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');useEffect(()=>{if(!focusVehicleId&&!focusCustomerId)return;const vehicle=focusVehicleId?data.vehicles.find(v=>v.id===focusVehicleId):undefined;const customer=focusCustomerId?data.customers.find(c=>c.id===focusCustomerId):undefined;setCreating(true);setVehicleId(focusVehicleId||'');setCustomerId(focusCustomerId||'');setTitle(vehicle?`Appuntamento ${[vehicle.brand,vehicle.model].filter(Boolean).join(' ')}`:customer?`Appuntamento ${[customer.first_name,customer.last_name].filter(Boolean).join(' ')}`:'Nuovo appuntamento');setPriority('NORMAL');setNote('');onFocusConsumed?.()},[focusVehicleId,focusCustomerId,focusKey]);const rows=useMemo(()=>data.calendarEvents.filter(active).filter(e=>e.starts_at).sort((a,b)=>String(a.starts_at).localeCompare(String(b.starts_at))),[data.calendarEvents]);const now=Date.now();const today=new Date().toDateString();const overdue=rows.filter(e=>{const d=new Date(e.starts_at!);return d.getTime()<now&&d.toDateString()!==today});const todayRows=rows.filter(e=>new Date(e.starts_at!).toDateString()===today);const upcoming=rows.filter(e=>new Date(e.starts_at!).getTime()>now&&new Date(e.starts_at!).toDateString()!==today);const create=async()=>{setBusy(true);setError('');try{await saveCalendarEvent({title,startsAt,priority,note,customerId:customerId||null,vehicleId:vehicleId||null,eventType:'APPOINTMENT'});setTitle('');setStartsAt('');setPriority('NORMAL');setCustomerId('');setVehicleId('');setNote('');setCreating(false);await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore salvataggio')}finally{setBusy(false)}};const done=async(e:CalendarEvent)=>{setBusy(true);setError('');try{await completeCalendarEvent(e);await onRefresh()}catch(err){setError(err instanceof Error?err.message:'Errore aggiornamento')}finally{setBusy(false)}};const group=(label:string,items:CalendarEvent[],danger=false)=><section className="calendar-group"><div className="section-title"><div><p className="eyebrow">{label}</p><h2>{items.length} {items.length===1?'voce':'voci'}</h2></div></div><div className="calendar-list">{items.map(e=><article key={e.id} className={`calendar-row ${danger?'calendar-overdue':''}`}><div className="calendar-date"><CalendarDays/><b>{fullDate(e.starts_at)}</b></div><div><h3>{e.title||'Evento'}</h3><p>{[customerName(data,e.customer_id),vehicleName(data,e.vehicle_id),e.note].filter(Boolean).join(' · ')||e.event_type||'Appuntamento'}</p></div><span>{e.starts_at?<><Clock/> {new Date(e.starts_at).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'})}</>:''}</span>{writable&&<button className="calendar-done" disabled={busy} onClick={()=>void done(e)} title="Segna completato"><CheckCircle2/></button>}</article>)}{!items.length&&<div className="empty-state">Nessuna voce.</div>}</div></section>;return <><div className="page-heading"><div><p className="eyebrow">SCADENZE E APPUNTAMENTI</p><h1>Calendario</h1><p>Scaduti prima, oggi subito sotto, poi il resto. Senza calendario pieno di rumore.</p></div>{writable&&<button className="primary-action" onClick={()=>setCreating(v=>!v)}>{creating?<X/>:<Plus/>}{creating?'Chiudi':'Nuovo appuntamento'}</button>}</div>{error&&<div className="form-error">{error}</div>}{creating&&<section className="calendar-create"><div className="workbench-grid"><label><span>Titolo</span><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Es. richiamare cliente / consegna / prova auto"/></label><label><span>Data e ora</span><input type="datetime-local" value={startsAt} onChange={e=>setStartsAt(e.target.value)}/></label><label><span>Cliente</span><select value={customerId} onChange={e=>setCustomerId(e.target.value)}><option value="">Nessun cliente</option>{data.customers.map(c=><option key={c.id} value={c.id}>{[c.first_name,c.last_name].filter(Boolean).join(' ')||'Cliente'}</option>)}</select></label><label><span>Auto</span><select value={vehicleId} onChange={e=>setVehicleId(e.target.value)}><option value="">Nessuna auto</option>{data.vehicles.filter(v=>!v.deleted_at).map(v=><option key={v.id} value={v.id}>{[v.brand,v.model,v.plate].filter(Boolean).join(' ')||'Auto'}</option>)}</select></label><label><span>Priorità</span><select value={priority} onChange={e=>setPriority(e.target.value)}><option value="LOW">Bassa</option><option value="NORMAL">Normale</option><option value="HIGH">Alta</option></select></label><label className="wide"><span>Nota</span><input value={note} onChange={e=>setNote(e.target.value)} placeholder="Dettaglio utile"/></label></div><button className="primary-action" disabled={busy||!title.trim()||!startsAt} onClick={()=>void create()}><Save/> Salva appuntamento</button></section>}{group('SCADUTI',overdue,true)}{group('OGGI',todayRows)}{group('PROSSIMI',upcoming)}</>}
