import type {TenantData,Vehicle} from '../types'
export type PriorityKind='PRICE'|'PHOTO'|'WORK'|'AGE'|'CALENDAR'|'CUSTOMER'|'DELIVERY'|'COLLECTION'
export interface PriorityItem { id:string; kind:PriorityKind; severity:1|2|3; title:string; detail:string; vehicleId?:string; customerId?:string; due?:string }
const terminal=new Set(['CONSEGNATA','VENDUTA','ANNULLATA'])
const sellable=new Set(['IN_VENDITA','IN_ARRIVO'])
const daysSince=(date?:string,now=new Date())=>date?Math.max(0,Math.floor((now.getTime()-new Date(`${date.slice(0,10)}T12:00:00`).getTime())/86400000)):0
const localDay=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`
const customerName=(first?:string,last?:string)=>[first,last].filter(Boolean).join(' ')||'Cliente'
export function vehicleAgeDays(vehicle:Vehicle,now=new Date()){return daysSince(vehicle.purchase_date||vehicle.created_at,now)}
export function buildPriorities(data:TenantData,now=new Date()):PriorityItem[]{const items:PriorityItem[]=[];const photos=new Map<string,number>();for(const m of data.media){if((m.kind||'PHOTO')==='PHOTO')photos.set(m.vehicle_id,(photos.get(m.vehicle_id)||0)+1)}for(const v of data.vehicles){if(v.deleted_at||terminal.has(v.status||''))continue;const name=[v.brand,v.model].filter(Boolean).join(' ')||'Veicolo';if(sellable.has(v.status||'')&&!Number(v.asking_price||0))items.push({id:`price:${v.id}`,kind:'PRICE',severity:3,title:`${name}: manca il prezzo`,detail:'Imposta il prezzo cliente per rendere la scheda realmente pronta alla vendita.',vehicleId:v.id});if(sellable.has(v.status||'')&&(photos.get(v.id)||0)===0)items.push({id:`photo:${v.id}`,kind:'PHOTO',severity:3,title:`${name}: mancano le foto`,detail:'Completa la scheda dal telefono prima della pubblicazione.',vehicleId:v.id});const age=vehicleAgeDays(v,now);if(v.status==='IN_VENDITA'&&age>=60)items.push({id:`age:${v.id}`,kind:'AGE',severity:age>=90?3:2,title:`${name}: ${age} giorni in stock`,detail:'Rivedi prezzo, foto o strategia commerciale.',vehicleId:v.id})}for(const w of data.workItems){if(['DONE','CANCELLED','CHIUSO'].includes(w.status||''))continue;if(w.due_date&&new Date(`${w.due_date}T23:59:59`).getTime()<now.getTime()){const v=data.vehicles.find(x=>x.id===w.vehicle_id);items.push({id:`work:${w.id}`,kind:'WORK',severity:3,title:w.title||'Lavoro scaduto',detail:`${v?[v.brand,v.model].filter(Boolean).join(' '):'Auto'} · scadenza superata`,vehicleId:w.vehicle_id,due:w.due_date})}}const today=localDay(now);for(const customer of data.customers){if(customer.deleted_at||!customer.next_step||!customer.next_contact_at)continue;const due=new Date(customer.next_contact_at);if(Number.isNaN(due.getTime()))continue;const dueDay=localDay(due);if(dueDay<=today){const overdue=due.getTime()<new Date(`${today}T00:00:00`).getTime();items.push({id:`customer:${customer.id}`,kind:'CUSTOMER',severity:overdue?3:2,title:`${customerName(customer.first_name,customer.last_name)}: ${customer.next_step}`,detail:overdue?'Follow-up cliente scaduto. Va gestito adesso.':'Follow-up cliente previsto oggi.',customerId:customer.id,due:customer.next_contact_at})}}for(const e of data.calendarEvents){if(['DONE','CANCELLED','CHIUSO'].includes(e.status||''))continue;if(!e.starts_at)continue;const eventDate=new Date(e.starts_at);if(Number.isNaN(eventDate.getTime()))continue;const eventDay=localDay(eventDate);if(eventDay<=today){const overdue=eventDate.getTime()<new Date(`${today}T00:00:00`).getTime();items.push({id:`cal:${e.id}`,kind:'CALENDAR',severity:overdue?3:2,title:e.title||'Appuntamento',detail:overdue?'Appuntamento o scadenza non ancora chiusa.':'Appuntamento o scadenza prevista oggi.',vehicleId:e.vehicle_id||undefined,customerId:e.customer_id||undefined,due:e.starts_at})}}for(const c of data.contracts){if(c.template_code==='VENDITA'&&['DELIVERY','DA_CONSEGNARE','READY_FOR_DELIVERY'].includes(c.sale_stage||''))items.push({id:`delivery:${c.id}`,kind:'DELIVERY',severity:3,title:'Consegna da completare',detail:'Vendita in fase di consegna: verifica saldo, documenti e checklist.',vehicleId:c.vehicle_id,customerId:c.customer_id})}return items.sort((a,b)=>b.severity-a.severity||String(a.due||'').localeCompare(String(b.due||''))).slice(0,30)}
